insert into survey_versions(id,survey_id,version,status,config) values(vid,sid,1,'draft','{"title":"水谷眼科診療所 患者様アンケート","description":"今後の診療・サービス向上のため、ご意見をお聞かせください。","introText":"お忙しいところ恐れ入りますが、アンケートにご協力ください。","anonymousText":"このアンケートは匿名です。氏名・連絡先は取得しません。","completionText":"ご回答ありがとうございました。いただいたご意見は、今後より良い診療環境づくりに活用させていただきます。","submitLabel":"回答を送信","primaryColor":"#147d74","backgroundColor":"#f2faf8","logoUrl":null,"iconUrl":null,"googleReviewUrl":null}'::jsonb) on conflict(id) do nothing;update surveys set current_draft_version_id=vid where id=sid;
